head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > gotoTime]<br/>Calendar 컴포넌트의 선택 시간을 지정한 시/분/초로 설정합니다.",
    "validation" : [
        "hour(필수) 파라미터로 컴포넌트의 선택 시간을 Number 또는 String 으로 설정합니다.",
        "hour 파라미터는 calendarValueType=yearMonthDateHour,yearMonthDateTime,yearMonthDateTimeSec 인 경우에 동작합니다.",
        "visibleHourList 속성이 설정된 경우 hour 파라미터는 문자열로 처리됩니다.",
        "minute(선택) 파라미터로 컴포넌트의 선택 분을 Number 또는 String 으로 설정합니다.",
        "minute 파라미터는 calendarValueType=yearMonthDateTime,yearMonthDateTimeSec 인 경우에 동작합니다.",
        "visibleMinList 속성이 설정된 경우 minute 파라미터는 문자열로 처리됩니다.",
        "second(선택) 파라미터로 컴포넌트의 선택 초를 Number 또는 String 으로 설정합니다.",
        "second 파라미터는 calendarValueType=yearMonthDateTimeSec 인 경우에 동작합니다.",
        "visibleSecList 속성이 설정된 경우 second 파라미터는 문자열로 처리됩니다.",
        "변경 전/후 시간이 다르면 onchange 이벤트가 발생합니다.",
        "calendarValueType=yearMonthDate, yearMonth 인 경우 아무 동작도 수행하지 않습니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        calendarValueType : con_calendarValueType.getText()
    }
    // 비어있지 않을 때만 visible*List 설정
    let vH = con_visibleHourList.getText();
    let vM = con_visibleMinList.getText();
    let vS = con_visibleSecList.getText();
    if (vH) properties.visibleHourList = vH;
    if (vM) properties.visibleMinList = vM;
    if (vS) properties.visibleSecList = vS;

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange"]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 선택일: 2025-11-11
}



// 시/분/초 SelectBox 의 현재 선택값 추출 (calendar 자식 selectbox 컴포넌트의 getText)
scwin.fn_getSbSelected = function (suffix) {
    let sbId = target1.id + "_selectbox_" + suffix;
    let sb = WebSquare.util.getComponentById(sbId);
    if (!sb) return '없음';
    if (typeof sb.getText === 'function') return sb.getText();
    if (typeof sb.getValue === 'function') return sb.getValue();
    return '(getText/getValue 메소드 없음)';
};



// gotoTime 호출 (선택된 케이스에 따라 분기)
// validation:
//  - case 1: gotoTime('14')           → hour 만 설정, yearMonthDateHour 에서 동작
//  - case 2: gotoTime('14', '30')     → hour + minute 설정, yearMonthDateTime 에서 동작
//  - case 3: gotoTime(9, 15, 30)      → hour + minute + second 설정, yearMonthDateTimeSec 에서 동작
//  - calendarValueType=yearMonthDate, yearMonth 인 경우 아무 동작 수행하지 않음
//  - visibleHourList/MinList/SecList 속성이 설정된 경우 각 파라미터가 문자열로 처리됨
scwin.btn_gotoTime_onclick = function (e) {
    let caseId = con_gotoCase.getValue();
    let argDesc;

    let beforeValue = target1.getValue();

    if (caseId === '1') {
        argDesc = "'14'";
        target1.gotoTime('14');
    } else if (caseId === '2') {
        argDesc = "'14', '30'";
        target1.gotoTime('14', '30');
    } else if (caseId === '3') {
        argDesc = "9, 15, 30";
        target1.gotoTime(9, 15, 30);
    }

    let afterValue = target1.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("[gotoTime 호출 전 getValue()] '" + beforeValue + "' / [gotoTime 인자] " + argDesc + " / [gotoTime 호출 후 getValue()] '" + afterValue + "'");

    // selectbox DOM 갱신 대기 후 선택값 조회
    setTimeout(function () {
        let hourSel = scwin.fn_getSbSelected('hour');
        let minSel = scwin.fn_getSbSelected('minute');
        let secSel = scwin.fn_getSbSelected('second');
        wf_body_bottom.getObj("scwin").setReturnValue("[시 선택값] '" + hourSel + "' / [분 선택값] '" + minSel + "' / [초 선택값] '" + secSel + "'");
    }, 300);
};



// 변경 전/후 시간이 다르면 onchange 이벤트 발생
// @spec validation
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생]");
};
